  const ES_SPECIALTY_CATS = ["\u0E01\u0E0E\u0E2B\u0E21\u0E32\u0E22 (Legal Spanish)", "\u0E27\u0E34\u0E28\u0E27\u0E01\u0E23\u0E23\u0E21 (Engineering Spanish)", "\u0E18\u0E38\u0E23\u0E01\u0E34\u0E08\u0E40\u0E0A\u0E34\u0E07\u0E25\u0E36\u0E01 (Business Spanish)"];
  function esVocabPool() {
    const out = [];
    const cats = VOCAB["lang-es"] || {};
    Object.keys(cats).forEach((cat) => {
      if (ES_SPECIALTY_CATS.includes(cat)) return;
      (cats[cat] || []).forEach((w, i) => out.push({ key: `lang-es::vocab-${cat}::${i}`, word: w.word, thai: w.thai }));
    });
    return out;
  }
  function genEsWordMeaningMc(pool, count) {
    const picked = shuffleArr(pool).slice(0, Math.min(count, pool.length));
    return picked.map((item) => {
      const distractors = shuffleArr(pool.filter((p) => p.word !== item.word)).slice(0, 3);
      const choices = shuffleArr([item.thai, ...distractors.map((d) => d.thai)]);
      return { type: "es-word-meaning-mc", word: item.word, correct: item.thai, choices };
    });
  }
