    { text: "\u0633\u064A\u0643\u0648\u0646 \u0627\u0644\u062C\u0648 \u0633\u064A\u0626\u064B\u0627 \u063A\u062F\u064B\u0627. \u0633\u062A\u0645\u0637\u0631 \u0648\u0633\u062A\u0647\u0628 \u0631\u064A\u0627\u062D. \u0644\u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u0623\u0641\u0636\u0644 \u0639\u062F\u0645 \u0627\u0644\u062E\u0631\u0648\u062C.", q: "\u0643\u064A\u0641 \u0633\u064A\u0643\u0648\u0646 \u0627\u0644\u062C\u0648 \u063A\u062F\u064B\u0627\u061F", choices: ["\u0645\u0645\u0637\u0631 \u0648\u0639\u0627\u0635\u0641", "\u062D\u0627\u0631 \u0648\u0645\u0634\u0645\u0633", "\u062B\u0644\u062C\u064A"], correct: "\u0645\u0645\u0637\u0631 \u0648\u0639\u0627\u0635\u0641" },
    { text: "\u0623\u0639\u0645\u0644 \u0641\u064A \u0645\u0643\u062A\u0628 \u0641\u064A \u0627\u0644\u0645\u062F\u064A\u0646\u0629. \u0623\u0630\u0647\u0628 \u0625\u0644\u0649 \u0627\u0644\u0639\u0645\u0644 \u0643\u0644 \u064A\u0648\u0645 \u0628\u0627\u0644\u062D\u0627\u0641\u0644\u0629. \u062A\u0633\u062A\u063A\u0631\u0642 \u0627\u0644\u0631\u062D\u0644\u0629 \u0646\u062D\u0648 \u062B\u0644\u0627\u062B\u064A\u0646 \u062F\u0642\u064A\u0642\u0629.", q: "\u0643\u064A\u0641 \u064A\u0630\u0647\u0628 \u0647\u0630\u0627 \u0627\u0644\u0634\u062E\u0635 \u0625\u0644\u0649 \u0627\u0644\u0639\u0645\u0644\u061F", choices: ["\u0628\u0627\u0644\u062D\u0627\u0641\u0644\u0629", "\u0628\u0627\u0644\u0633\u064A\u0627\u0631\u0629", "\u0633\u064A\u0631\u064B\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u062F\u0627\u0645"], correct: "\u0628\u0627\u0644\u062D\u0627\u0641\u0644\u0629" }
