  function genKhPassageMc(dataset, count) {
    const picked = shuffleArr(dataset).slice(0, Math.min(count, dataset.length));
    const out = [];
    picked.forEach((p) => {
      p.questions.forEach((q) => out.push({ type: "passage-mc", text: p.text, q: q.q, choices: shuffleArr(q.choices), correct: q.correct }));
    });
    return out;
  }
